const P={
  fr:{title:"Politique de Confidentialité",sub:"Tamini Insurance SA s'engage à protéger vos données personnelles avec la même rigueur que votre patrimoine.",
    updated:"Dernière mise à jour : Juillet 2026",
    sections:[
      {h:"Cadre juridique applicable",b:["Cette politique est régie par la Loi n°019/AN/23/9ème L du 6 juillet 2025 relative au Code du Numérique, notamment son Livre Premier sur la protection des données personnelles, ainsi que par les textes d'application de la Commission Nationale de Protection des Données Personnelles.","Compte tenu de l'activité d'assurance de Tamini à Djibouti, cette politique s'inscrit également dans le cadre de la Loi n°40/AN/99/4ème L du 8 juin 1999 réglementant les compagnies d'assurance, ainsi que des règles prudentielles, comptables et sectorielles applicables."]},
      {h:"1. Introduction",b:["Tamini Insurance SA (« Tamini », « nous ») est une compagnie d'assurance basée à Djibouti, proposant des solutions Takaful pour particuliers, professionnels et entreprises : automobile, habitation, voyage, maritime, entreprise et assurance personnelle.","Tamini opère selon les principes de l'assurance coopérative et du Takaful, avec un engagement de transparence, d'équité, d'entraide et de protection du client.","Cette politique explique comment Tamini collecte, utilise, conserve, partage et protège vos données personnelles lors de vos interactions avec nos canaux digitaux : site web, application mobile, formulaires, réseaux sociaux et services associés."]},
      {h:"2. Qui sommes-nous",b:["Tamini Insurance SA est le responsable de traitement de vos données personnelles.","Société : Tamini Insurance SA","Adresse : Place du 27 Juin, Djibouti, République de Djibouti","Téléphone : +253 21 35 04 03","WhatsApp : +253 77 23 92 92 (commercial) · +253 77 09 41 41 (assistant)","Email : info@tamini-insurance.com"]},
      {h:"3. Données que nous collectons",b:["Données fournies : identité, coordonnées, informations de contrat et de devis, données de sinistres (documents, photos, rapports), informations financières et de paiement, échanges (téléphone, email, WhatsApp).","Données collectées automatiquement : adresse IP, navigateur, appareil, données d'utilisation du site, cookies et données analytiques, localisation (si activée).","Données de tiers : intermédiaires, courtiers, garages, experts, prestataires d'assistance, partenaires de paiement, autorités publiques ou judiciaires si requis."]},
      {h:"4. Pourquoi nous utilisons vos données",b:["Fournir nos services d'assurance : devis, contrats, avenants, renouvellements.","Traiter les sinistres, organiser l'assistance et le règlement des indemnisations.","Exploiter, sécuriser et améliorer notre site et nos services digitaux.","Communiquer avec nos clients, prospects, bénéficiaires et partenaires.","Gérer la facturation, la comptabilité et nos obligations fiscales.","Prévenir la fraude et assurer la gestion des risques.","Administrer les opérations d'assurance Takaful, y compris les données nécessaires à cette administration."]},
      {h:"5. Bases légales",b:["Exécution du contrat d'assurance.","Démarches précontractuelles (préparation d'un devis).","Respect de nos obligations légales et réglementaires.","Intérêt légitime de Tamini (prévention de la fraude, sécurité, amélioration des services).","Votre consentement, notamment pour la prospection ou les cookies non essentiels.","Protection des intérêts vitaux en cas d'urgence."]},
      {h:"6. Données sensibles",b:["Tamini traite des données sensibles uniquement lorsque cela est nécessaire et proportionné : données de santé, données de sinistres corporels, ou données requises pour l'administration de produits Takaful.","Des mesures de protection renforcées s'appliquent : accès strictement limité au personnel autorisé, confidentialité, traçabilité, et consentement explicite lorsque requis par la loi."]},
      {h:"7. Cookies et technologies de suivi",b:["Tamini utilise des cookies pour faire fonctionner le site, améliorer la performance, sécuriser les services et mesurer l'audience. Votre consentement est recueilli pour les cookies non essentiels. Vous pouvez gérer vos préférences via votre navigateur."]},
      {h:"8. Partage des données",b:["Tamini partage vos données uniquement lorsque nécessaire : prestataires techniques, partenaires d'assurance et de réassurance, garages et experts, prestataires de paiement, autorités publiques si la loi l'exige.","Tamini ne vend jamais vos données personnelles. Les paiements par carte ne sont pas stockés par Tamini ; ils sont traités par des prestataires appliquant les standards PCI-DSS."]},
      {h:"9. Transferts internationaux",b:["Certaines données peuvent être hébergées hors de la République de Djibouti, notamment via des services cloud. Tamini applique des mesures de sécurité techniques appropriées pour protéger ces données contre tout accès non autorisé, perte ou divulgation."]},
      {h:"10. Durée de conservation",b:["Données de contrat : durée du contrat + 10 ans.","Données de sinistres : 10 ans à compter de la clôture du dossier.","Données comptables : 10 ans conformément aux obligations comptables.","Données de prospection : 3 ans après le dernier contact."]},
      {h:"11. Sécurité et protection dès la conception",b:["Tamini applique des mesures de sécurité techniques, organisationnelles et physiques appropriées : chiffrement des données en transit, contrôles d'accès, sauvegardes, sensibilisation du personnel. Le principe de protection des données dès la conception guide le développement de tous nos services digitaux."]},
      {h:"12. Violations de données",b:["En cas de violation de données susceptible d'affecter vos droits, Tamini notifie la Commission compétente sans délai excessif et au plus tard 72 heures après en avoir eu connaissance, et informe les personnes concernées si le risque est élevé."]},
      {h:"13. Vos droits",b:["Droit d'accès à vos données.","Droit de rectification des données inexactes.","Droit à l'effacement, dans les limites légales applicables.","Droit d'opposition à certains traitements.","Droit de retirer votre consentement à tout moment.","Droit à la portabilité de vos données, le cas échéant.","Droit de saisir la Commission compétente.","Pour exercer ces droits gratuitement, contactez-nous à l'adresse indiquée en section 2."]},
      {h:"14. Confidentialité des mineurs",b:["Nos services digitaux ne sont pas destinés aux personnes de moins de 18 ans. Des données relatives à un enfant peuvent être traitées lorsque celui-ci est désigné bénéficiaire ou assuré dans le cadre d'un contrat souscrit par un adulte responsable, dans la stricte limite nécessaire à la gestion du contrat."]},
      {h:"15. Modifications de cette politique",b:["Cette politique peut être mise à jour périodiquement. La version la plus récente est publiée sur notre site avec sa date de mise à jour. En cas de changement substantiel, nous vous informons par les moyens appropriés."]},
      {h:"16. Contact",b:["Pour toute question relative à cette politique ou au traitement de vos données :","Tamini Insurance SA — Place du 27 Juin, Djibouti, République de Djibouti","Email : info@tamini-insurance.com · Téléphone : +253 21 35 04 03 · WhatsApp : +253 77 23 92 92"]},
    ]},
  en:{title:"Privacy Policy",sub:"Tamini Insurance SA is committed to protecting your personal data with the same rigor as your assets.",
    updated:"Last updated: July 2026",
    sections:[
      {h:"Applicable Legal Framework",b:["This Policy is governed by Law No. 019/AN/23/9th L of 6 July 2025 on the Digital Code, particularly Book One on personal data protection, and the implementing texts of the National Commission for the Protection of Personal Data.","Given Tamini's insurance activity in Djibouti, this Policy is also read alongside Law No. 40/AN/99/4th L of 8 June 1999 regulating insurance companies, and applicable prudential, accounting and sector-specific rules."]},
      {h:"1. Introduction",b:["Tamini Insurance SA (\u201CTamini\u201D, \u201Cwe\u201D) is an insurance company based in Djibouti, offering Takaful solutions for individuals, professionals and businesses: motor, home, travel, marine, business and personal insurance.","Tamini operates under cooperative insurance and Takaful principles, committed to transparency, fairness, mutual assistance and customer protection.","This Policy explains how Tamini collects, uses, retains, shares and protects your personal data through our digital channels: website, mobile app, forms, social media and related services."]},
      {h:"2. Who We Are",b:["Tamini Insurance SA is the data controller for your personal data.","Company: Tamini Insurance SA","Address: Place du 27 Juin, Djibouti, Republic of Djibouti","Phone: +253 21 35 04 03","WhatsApp: +253 77 23 92 92 (sales) · +253 77 09 41 41 (assistant)","Email: info@tamini-insurance.com"]},
      {h:"3. Data We Collect",b:["Data you provide: identity, contact details, policy and quote information, claims data (documents, photos, reports), financial and billing information, communications (phone, email, WhatsApp).","Data collected automatically: IP address, browser, device, website usage data, cookies and analytics, location (if enabled).","Data from third parties: intermediaries, brokers, garages, experts, assistance providers, payment partners, public authorities if required."]},
      {h:"4. Why We Use Your Data",b:["Providing insurance services: quotes, contracts, endorsements, renewals.","Handling claims, organizing assistance and compensation.","Operating, securing and improving our website and digital services.","Communicating with customers, prospects, beneficiaries and partners.","Managing billing, accounting and tax obligations.","Preventing fraud and managing risk.","Administering Takaful insurance operations, including data necessary for such administration."]},
      {h:"5. Legal Bases",b:["Performance of the insurance contract.","Pre-contractual steps (preparing a quote).","Compliance with legal and regulatory obligations.","Tamini's legitimate interests (fraud prevention, security, service improvement).","Your consent, notably for marketing or non-essential cookies.","Protection of vital interests in emergencies."]},
      {h:"6. Sensitive Personal Data",b:["Tamini processes sensitive data only where necessary and proportionate: health data, bodily injury claims data, or data required for Takaful product administration.","Enhanced protection measures apply: strictly limited access to authorized personnel, confidentiality, traceability, and explicit consent where required by law."]},
      {h:"7. Cookies and Tracking",b:["Tamini uses cookies to operate the website, improve performance, secure services and measure audience. Consent is obtained for non-essential cookies. You can manage preferences via your browser."]},
      {h:"8. Data Sharing",b:["Tamini shares data only where necessary: technical providers, insurance and reinsurance partners, garages and experts, payment providers, public authorities if legally required.","Tamini never sells your personal data. Card payments are not stored by Tamini; they are processed by providers applying PCI-DSS standards."]},
      {h:"9. International Transfers",b:["Certain data may be hosted outside the Republic of Djibouti, particularly via cloud services. Tamini applies appropriate technical security measures to protect this data against unauthorized access, loss or disclosure."]},
      {h:"10. Data Retention",b:["Contract data: duration of contract + 10 years.","Claims data: 10 years from file closure.","Accounting data: 10 years per accounting obligations.","Prospecting data: 3 years after last contact."]},
      {h:"11. Security and Privacy by Design",b:["Tamini applies appropriate technical, organizational and physical security measures: encryption in transit, access controls, backups, staff awareness. Privacy by design guides the development of all our digital services."]},
      {h:"12. Data Breaches",b:["In the event of a breach likely to affect your rights, Tamini notifies the competent Commission without undue delay and within 72 hours of becoming aware, and informs affected individuals if the risk is high."]},
      {h:"13. Your Rights",b:["Right of access to your data.","Right to rectification of inaccurate data.","Right to erasure, within applicable legal limits.","Right to object to certain processing.","Right to withdraw consent at any time.","Right to data portability, where applicable.","Right to lodge a complaint with the competent Commission.","To exercise these rights free of charge, contact us at the address in Section 2."]},
      {h:"14. Children's Privacy",b:["Our digital services are not intended for individuals under 18. Data relating to a child may be processed where the child is a designated beneficiary or insured under a contract taken out by a responsible adult, strictly limited to what is necessary for contract management."]},
      {h:"15. Changes to This Policy",b:["This Policy may be updated periodically. The most recent version is published on our website with its update date. In the event of material change, we notify you through appropriate means."]},
      {h:"16. Contact",b:["For any question regarding this Policy or the processing of your data:","Tamini Insurance SA — Place du 27 Juin, Djibouti, Republic of Djibouti","Email: info@tamini-insurance.com · Phone: +253 21 35 04 03 · WhatsApp: +253 77 23 92 92"]},
    ]},

  ar:{title:"سياسة الخصوصية",sub:"تلتزم شركة تأميني للتأمين بحماية بياناتكم الشخصية بنفس الصرامة التي نحمي بها ممتلكاتكم.",
    updated:"آخر تحديث: يوليو 2026",
    sections:[
      {h:"الإطار القانوني المعمول به",b:["تخضع هذه السياسة للقانون رقم 019/AN/23/9ème L الصادر في 6 يوليو 2025 المتعلق بقانون الرقمنة، ولا سيما الكتاب الأول المتعلق بحماية البيانات الشخصية، وكذلك النصوص التطبيقية للجنة الوطنية لحماية البيانات الشخصية.","نظراً لنشاط تأميني في مجال التأمين بجيبوتي، تُقرأ هذه السياسة أيضاً في ضوء القانون رقم 40/AN/99/4ème L الصادر في 8 يونيو 1999 المنظم لشركات التأمين، والقواعد الاحترازية والمحاسبية والقطاعية المعمول بها."]},
      {h:"1. مقدمة",b:["شركة Tamini Insurance SA («تأميني»، «نحن») هي شركة تأمين مقرها جيبوتي، تقدم حلول تكافل للأفراد والمهنيين والشركات: السيارات، المسكن، السفر، البحري، الأعمال والتأمين الشخصي.","تعمل تأميني وفق مبادئ التأمين التعاوني والتكافل، مع التزام بالشفافية والعدالة والتضامن وحماية العملاء.","توضح هذه السياسة كيفية جمع تأميني لبياناتكم الشخصية واستخدامها والاحتفاظ بها ومشاركتها وحمايتها عبر قنواتنا الرقمية: الموقع الإلكتروني، التطبيق، النماذج، وسائل التواصل الاجتماعي والخدمات ذات الصلة."]},
      {h:"2. من نحن",b:["شركة Tamini Insurance SA هي المسؤولة عن معالجة بياناتكم الشخصية.","الشركة: Tamini Insurance SA","العنوان: ساحة 27 يونيو، جيبوتي، جمهورية جيبوتي","الهاتف: 253+ 21 35 04 03","واتساب: 253+ 77 23 92 92 (تجاري) · 253+ 77 09 41 41 (المساعد)","البريد الإلكتروني: info@tamini-insurance.com"]},
      {h:"3. البيانات التي نجمعها",b:["البيانات المقدمة منكم: الهوية، معلومات الاتصال، معلومات العقد والعرض، بيانات المطالبات (وثائق، صور، تقارير)، المعلومات المالية وبيانات الدفع، المراسلات (هاتف، بريد إلكتروني، واتساب).","البيانات المجمعة تلقائياً: عنوان IP، المتصفح، الجهاز، بيانات استخدام الموقع، ملفات تعريف الارتباط والتحليلات، الموقع الجغرافي (إن تم تفعيله).","بيانات من أطراف ثالثة: الوسطاء، السماسرة، الكراجات، الخبراء، مقدمو المساعدة، شركاء الدفع، السلطات العامة إن اقتضى الأمر."]},
      {h:"4. لماذا نستخدم بياناتكم",b:["تقديم خدمات التأمين: عروض الأسعار، العقود، الملاحق، التجديدات.","معالجة المطالبات، تنظيم المساعدة والتعويض.","تشغيل وتأمين وتحسين موقعنا وخدماتنا الرقمية.","التواصل مع العملاء والعملاء المحتملين والمستفيدين والشركاء.","إدارة الفوترة والمحاسبة والالتزامات الضريبية.","منع الاحتيال وإدارة المخاطر.","إدارة عمليات التأمين التكافلي، بما في ذلك البيانات اللازمة لهذه الإدارة."]},
      {h:"5. الأسس القانونية",b:["تنفيذ عقد التأمين.","الخطوات التعاقدية المسبقة (إعداد عرض سعر).","الامتثال للالتزامات القانونية والتنظيمية.","المصلحة المشروعة لتأميني (منع الاحتيال، الأمن، تحسين الخدمات).","موافقتكم، لا سيما للتسويق أو ملفات تعريف الارتباط غير الأساسية.","حماية المصالح الحيوية في حالات الطوارئ."]},
      {h:"6. البيانات الحساسة",b:["تعالج تأميني البيانات الحساسة فقط عند الضرورة والتناسب: البيانات الصحية، بيانات مطالبات الإصابات الجسدية، أو البيانات المطلوبة لإدارة منتجات التكافل.","تُطبق تدابير حماية معززة: وصول محدود بشكل صارم للموظفين المخولين، السرية، إمكانية التتبع، والموافقة الصريحة عند الاقتضاء القانوني."]},
      {h:"7. ملفات تعريف الارتباط وتقنيات التتبع",b:["تستخدم تأميني ملفات تعريف الارتباط لتشغيل الموقع وتحسين الأداء وتأمين الخدمات وقياس الجمهور. تُجمع موافقتكم لملفات تعريف الارتباط غير الأساسية. يمكنكم إدارة تفضيلاتكم عبر متصفحكم."]},
      {h:"8. مشاركة البيانات",b:["تشارك تأميني البيانات فقط عند الضرورة: مقدمو الخدمات التقنية، شركاء التأمين وإعادة التأمين، الكراجات والخبراء، مقدمو خدمات الدفع، السلطات العامة إن اقتضى القانون ذلك.","لا تبيع تأميني بياناتكم الشخصية أبداً. لا تُخزَّن مدفوعات البطاقات لدى تأميني؛ بل تُعالَج من قبل مقدمي خدمات يطبقون معايير PCI-DSS."]},
      {h:"9. التحويلات الدولية",b:["قد تُستضاف بعض البيانات خارج جمهورية جيبوتي، لا سيما عبر خدمات الحوسبة السحابية. تُطبق تأميني تدابير أمنية تقنية مناسبة لحماية هذه البيانات من الوصول غير المصرح به أو الفقدان أو الإفشاء."]},
      {h:"10. مدة الاحتفاظ بالبيانات",b:["بيانات العقد: مدة العقد + 10 سنوات.","بيانات المطالبات: 10 سنوات من إغلاق الملف.","البيانات المحاسبية: 10 سنوات وفقاً للالتزامات المحاسبية.","بيانات التنقيب: 3 سنوات بعد آخر اتصال."]},
      {h:"11. الأمن والخصوصية حسب التصميم",b:["تُطبق تأميني تدابير أمنية تقنية وتنظيمية ومادية مناسبة: تشفير البيانات أثناء النقل، ضوابط الوصول، النسخ الاحتياطي، توعية الموظفين. يوجّه مبدأ الخصوصية حسب التصميم تطوير جميع خدماتنا الرقمية."]},
      {h:"12. خروقات البيانات",b:["في حالة وقوع خرق يُحتمل أن يؤثر على حقوقكم، تُخطر تأميني اللجنة المختصة دون تأخير لا مبرر له وفي غضون 72 ساعة من علمها به، وتُبلّغ الأشخاص المتأثرين إذا كانت المخاطر مرتفعة."]},
      {h:"13. حقوقكم",b:["الحق في الوصول إلى بياناتكم.","الحق في تصحيح البيانات غير الدقيقة.","الحق في المحو، ضمن الحدود القانونية المعمول بها.","الحق في الاعتراض على بعض المعالجات.","الحق في سحب موافقتكم في أي وقت.","الحق في نقل بياناتكم، عند الاقتضاء.","الحق في تقديم شكوى إلى اللجنة المختصة.","لممارسة هذه الحقوق مجاناً، تواصلوا معنا على العنوان المذكور في القسم 2."]},
      {h:"14. خصوصية القُصَّر",b:["خدماتنا الرقمية ليست موجهة للأشخاص دون 18 عاماً. يمكن معالجة بيانات متعلقة بطفل عندما يكون مستفيداً أو مؤمَّناً عليه بموجب عقد أبرمه شخص بالغ مسؤول، وذلك في أضيق الحدود اللازمة لإدارة العقد."]},
      {h:"15. التعديلات على هذه السياسة",b:["يمكن تحديث هذه السياسة دورياً. تُنشر أحدث نسخة على موقعنا مع تاريخ تحديثها. في حالة حدوث تغيير جوهري، نُبلغكم بالوسائل المناسبة."]},
      {h:"16. الاتصال",b:["لأي سؤال يتعلق بهذه السياسة أو بمعالجة بياناتكم:","Tamini Insurance SA — ساحة 27 يونيو، جيبوتي، جمهورية جيبوتي","البريد الإلكتروني: info@tamini-insurance.com · الهاتف: 253+ 21 35 04 03 · واتساب: 253+ 77 23 92 92"]},
    ]},
};

export default function PrivacyPolicy(){
  const[lang,setLang]=useState("fr");
  const t=P[lang];
  const rtl=lang==="ar";
  return(
    <div dir={rtl?"rtl":"ltr"} style={{fontFamily:rtl?"'Cairo','Inter',sans-serif":"'Inter',system-ui,sans-serif",color:"#1E293B",background:"#fff",minHeight:"100vh"}}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800&family=Inter:wght@400;500;600;700&family=Cairo:wght@400;600;700&display=swap');*{box-sizing:border-box}`}</style>

      <div style={{background:"linear-gradient(135deg,#0B1F4D,#0d2a5e)",padding:"64px 24px 56px",textAlign:"center",position:"relative"}}>
        <div style={{position:"absolute",top:20,right:24,display:"flex",borderRadius:8,overflow:"hidden",border:"1px solid rgba(255,255,255,.2)"}}>
          {["fr","en","ar"].map(l=><button key={l} onClick={()=>setLang(l)} style={{padding:"6px 14px",border:"none",fontSize:12,fontWeight:700,cursor:"pointer",background:lang===l?"#6EC026":"transparent",color:"#fff"}}>{l==="ar"?"ع":l.toUpperCase()}</button>)}
        </div>
        <h1 style={{fontFamily:"'Playfair Display',serif",fontSize:"clamp(28px,4vw,42px)",fontWeight:800,color:"#fff",marginBottom:14}}>{t.title}</h1>
        <p style={{fontSize:15,color:"rgba(255,255,255,.65)",maxWidth:560,margin:"0 auto",lineHeight:1.7}}>{t.sub}</p>
        <p style={{fontSize:12,color:"#6EC026",marginTop:16,fontWeight:600}}>{t.updated}</p>
      </div>

      <div style={{maxWidth:800,margin:"0 auto",padding:"48px 24px 80px"}}>
        {t.sections.map((s,i)=>(
          <div key={i} style={{marginBottom:36,paddingBottom:i<t.sections.length-1?32:0,borderBottom:i<t.sections.length-1?"1px solid #f1f5f9":"none"}}>
            <h2 style={{fontFamily:"'Playfair Display',serif",fontSize:19,fontWeight:700,color:"#0B1F4D",marginBottom:14}}>{s.h}</h2>
            {s.b.map((p,pi)=>(
              <p key={pi} style={{fontSize:14,color:"#475569",lineHeight:1.8,marginBottom:10}}>{p}</p>
            ))}
          </div>
        ))}
      </div>

      <div style={{background:"#F8FAFF",padding:"32px 24px",textAlign:"center",borderTop:"1px solid #e8ecf0"}}>
        <p style={{fontSize:13,color:"#64748b"}}>Tamini Insurance SA · Place du 27 Juin, Djibouti · +253 21 35 04 03</p>
      </div>
    </div>
  );
}
